# pylint: disable=C0301,W0613
"""
coverage test for autocell, deployed on jn-cell08
mode: routine commit local
trigger by jenkins
"""

import os
import sys
import logging

# 配置日志
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

MODE = os.environ.get("MODE", "routine")


class BaseCoverageJob:
    """Coverage 任务基类"""

    def __init__(self, mode):
        self.mode = mode

    def execute(self):
        """执行 coverage 任务"""
        raise NotImplementedError("子类必须实现 execute 方法")

    def validate(self):
        """验证环境配置"""
        logger.info(f"Validating environment for mode: {self.mode}")
        return True


class BaseSummaryJob:
    """Summary 任务基类"""

    def __init__(self, mode):
        self.mode = mode

    def generate_summary(self):
        """生成 summary 报告"""
        raise NotImplementedError("子类必须实现 generate_summary 方法")

    def report(self):
        """输出报告"""
        raise NotImplementedError("子类必须实现 report 方法")


class RoutineCoverageJob(BaseCoverageJob):
    """Routine 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("routine")

    def execute(self):
        """执行 routine coverage"""
        logger.info("Starting routine coverage")
        if not self.validate():
            raise RuntimeError("Routine coverage validation failed")
        print("routine coverage")
        logger.info("Routine coverage completed")


class CommitCoverageJob(BaseCoverageJob):
    """Commit 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("commit")

    def execute(self):
        """执行 commit coverage"""
        logger.info("Starting commit coverage")
        if not self.validate():
            raise RuntimeError("Commit coverage validation failed")
        print("commit coverage")
        logger.info("Commit coverage completed")


class LocalCoverageJob(BaseCoverageJob):
    """Local 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("local")

    def execute(self):
        """执行 local coverage"""
        logger.info("Starting local coverage")
        if not self.validate():
            raise RuntimeError("Local coverage validation failed")
        print("local coverage")
        logger.info("Local coverage completed")


class CoverageFactory:
    """Coverage 任务工厂类"""

    @staticmethod
    def create_job(mode):
        """根据 mode 创建对应的 coverage 任务"""
        job_map = {
            "routine": RoutineCoverageJob,
            "commit": CommitCoverageJob,
            "local": LocalCoverageJob,
        }

        job_class = job_map.get(mode)
        if job_class is None:
            raise ValueError(f"Unknown mode: {mode}")

        return job_class()


def main():
    """主入口函数"""
    try:
        logger.info(f"Starting coverage with MODE: {MODE}")
        job = CoverageFactory.create_job(MODE)
        job.execute()
    except ValueError as e:
        logger.error(f"Configuration error: {e}")
        print("unknown mode")
    except Exception as e:
        logger.error(f"Execution error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
"
